<?php
declare(strict_types=1);
require dirname(__DIR__).'/vendor/autoload.php';
use MarketForecast\Database\Connection;use MarketForecast\Reliability\{FrfWindowAggregator,ReliabilityRepository};
$db=$argv[1]??dirname(__DIR__).'/database/forecast.sqlite';$pdo=Connection::open($db);$rows=$pdo->query("SELECT fp.experiment_id,ao.actual_price_time,er.evaluated_at,er.direction_correct,er.brier_score,er.absolute_error_pct FROM final_predictions fp JOIN experiments e ON e.id=fp.experiment_id JOIN forecast_pairs p ON p.id=fp.forecast_pair_id JOIN final_predictions ai ON ai.forecast_pair_id=p.id AND ai.source_type='AI' JOIN actual_outcomes ao ON ao.final_prediction_id=fp.id JOIN evaluation_results er ON er.final_prediction_id=fp.id WHERE fp.source_type='QUANT' AND e.ai_activation_at IS NOT NULL AND fp.generated_at>=e.ai_activation_at AND ai.generated_at>=e.ai_activation_at")->fetchAll(PDO::FETCH_ASSOC);$by=[];foreach($rows as $r)$by[(int)$r['experiment_id']][]=$r;$agg=new FrfWindowAggregator();$repo=new ReliabilityRepository($pdo);$created=0;$end=new DateTimeImmutable('now');foreach($by as $experiment=>$records){foreach($agg->calculate($records,$end) as $window=>$score){$run=$repo->createRun(['experiment_id'=>$experiment,'source_type'=>'QUANT','window_code'=>$window,'window_start'=>null,'window_end'=>$end->format('c'),'calculation_version'=>'FRF_V2_ROLLING','status'=>'FINALIZED','resolved_n'=>$score['resolved_n'],'created_at'=>gmdate('c')]);if($run!==null){$repo->saveScore($run,['fps'=>$score['fps'],'ecs'=>$score['ecs'],'frs'=>$score['frs'],'fps_label'=>(new \MarketForecast\Reliability\FrfCalculator())->label($score['fps'],'fps'),'ecs_label'=>(new \MarketForecast\Reliability\FrfCalculator())->label($score['ecs'],'ecs'),'frs_label'=>(new \MarketForecast\Reliability\FrfCalculator())->label($score['frs'],'frs'),'diagnostics'=>$score['diagnostics'],'created_at'=>gmdate('c')]);$created++;}}}echo json_encode(['frf_runs_created'=>$created,'source_records'=>count($rows)],JSON_THROW_ON_ERROR).PHP_EOL;
